// Geometry helpers, snapping and connector routing (straight and orthogonal).
const DEG = Math.PI / 180;
const MARGIN = 100;
const BEND_PENALTY = 40;

const r6 = (v) => Math.round(v * 1e6) / 1e6;

export function toPoint(p) {
  return Array.isArray(p) ? [Number(p[0]), Number(p[1])] : [Number(p.x), Number(p.y)];
}

export function rotatePoint(px, py, cx, cy, deg) {
  const a = deg * DEG;
  const c = Math.cos(a);
  const s = Math.sin(a);
  const dx = px - cx;
  const dy = py - cy;
  return [cx + dx * c - dy * s, cy + dx * s + dy * c];
}

export function centerOf(el) {
  return [el.x + el.width / 2, el.y + el.height / 2];
}

// Axis-aligned bounding box of a (possibly rotated) shape.
export function aabbOf(el) {
  const [cx, cy] = centerOf(el);
  const rot = el.rotation || 0;
  const corners = [
    [el.x, el.y],
    [el.x + el.width, el.y],
    [el.x + el.width, el.y + el.height],
    [el.x, el.y + el.height],
  ].map(([x, y]) => rotatePoint(x, y, cx, cy, rot));
  const xs = corners.map((p) => p[0]);
  const ys = corners.map((p) => p[1]);
  const x = Math.min(...xs);
  const y = Math.min(...ys);
  return { x, y, width: Math.max(...xs) - x, height: Math.max(...ys) - y };
}

export function unionBox(boxes) {
  let x0 = Infinity;
  let y0 = Infinity;
  let x1 = -Infinity;
  let y1 = -Infinity;
  for (const b of boxes) {
    x0 = Math.min(x0, b.x);
    y0 = Math.min(y0, b.y);
    x1 = Math.max(x1, b.x + b.width);
    y1 = Math.max(y1, b.y + b.height);
  }
  return { x: x0, y: y0, width: x1 - x0, height: y1 - y0 };
}

// Rotation-aware containment test for the shape's outline.
export function containsPoint(el, px, py) {
  const [cx, cy] = centerOf(el);
  const [lx, ly] = rotatePoint(px, py, cx, cy, -(el.rotation || 0));
  const hw = el.width / 2;
  const hh = el.height / 2;
  const dx = lx - cx;
  const dy = ly - cy;
  if (el.type === 'ellipse' && hw > 0 && hh > 0) {
    return (dx * dx) / (hw * hw) + (dy * dy) / (hh * hh) <= 1;
  }
  if (el.type === 'diamond' && hw > 0 && hh > 0) {
    return Math.abs(dx) / hw + Math.abs(dy) / hh <= 1;
  }
  return Math.abs(dx) <= hw && Math.abs(dy) <= hh;
}

// Point where the segment from the element centre towards `toward` leaves the outline.
export function boundaryToward(el, toward) {
  const [cx, cy] = centerOf(el);
  const [tx, ty] = toward;
  const inside = (t) => containsPoint(el, cx + (tx - cx) * t, cy + (ty - cy) * t);
  if (!inside(0)) return [cx, cy];
  if (inside(1)) return [tx, ty];
  let lo = 0;
  let hi = 1;
  for (let i = 0; i < 50; i++) {
    const m = (lo + hi) / 2;
    if (inside(m)) lo = m;
    else hi = m;
  }
  return [cx + (tx - cx) * lo, cy + (ty - cy) * lo];
}

// Midpoint of a side, rotated with the element. Returns null for unknown sides.
export function sideAnchor(el, side) {
  const { x, y, width: w, height: h } = el;
  const pts = {
    top: [x + w / 2, y],
    bottom: [x + w / 2, y + h],
    left: [x, y + h / 2],
    right: [x + w, y + h / 2],
  };
  const p = pts[side];
  if (!p) return null;
  const [cx, cy] = centerOf(el);
  return rotatePoint(p[0], p[1], cx, cy, el.rotation || 0);
}

// Snap a point ({x,y} or [x,y]) to guides within tolerance, otherwise to the grid.
export function snap(point, opts = {}) {
  const { grid, guides, tolerance = 5 } = opts;
  const isArr = Array.isArray(point);
  const x0 = isArr ? Number(point[0]) : Number(point.x);
  const y0 = isArr ? Number(point[1]) : Number(point.y);
  const xs = [];
  const ys = [];
  if (guides && !Array.isArray(guides) && typeof guides === 'object') {
    xs.push(...(guides.x || []));
    ys.push(...(guides.y || []));
  } else if (Array.isArray(guides)) {
    for (const g of guides) {
      if (Array.isArray(g)) {
        xs.push(g[0]);
        ys.push(g[1]);
      } else if (g && typeof g === 'object') {
        if (g.x !== undefined) xs.push(g.x);
        if (g.y !== undefined) ys.push(g.y);
      }
    }
  }
  const pick = (v, step, lines) => {
    let best = null;
    let bd = tolerance;
    for (const t of lines) {
      const d = Math.abs(t - v);
      if (d <= bd) {
        bd = d;
        best = t;
      }
    }
    if (best !== null) return best;
    return step ? Math.round(v / step) * step : v;
  };
  const x = pick(x0, grid, xs);
  const y = pick(y0, grid, ys);
  return isArr ? [x, y] : { x, y };
}

function dedupeAndSimplify(pts) {
  const out = [];
  for (const p of pts) {
    const q = [r6(p[0]), r6(p[1])];
    const last = out[out.length - 1];
    if (last && last[0] === q[0] && last[1] === q[1]) continue;
    out.push(q);
  }
  const res = [];
  for (let i = 0; i < out.length; i++) {
    if (i > 0 && i < out.length - 1) {
      const a = out[i - 1];
      const b = out[i];
      const c = out[i + 1];
      if ((a[0] === b[0] && b[0] === c[0]) || (a[1] === b[1] && b[1] === c[1])) continue;
    }
    res.push(out[i]);
  }
  return res;
}

class MinHeap {
  constructor() {
    this.a = [];
  }

  get size() {
    return this.a.length;
  }

  push(k, v) {
    const a = this.a;
    a.push([k, v]);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p][0] <= a[i][0]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }

  pop() {
    const a = this.a;
    const top = a[0];
    const last = a.pop();
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let m = i;
        if (l < a.length && a[l][0] < a[m][0]) m = l;
        if (r < a.length && a[r][0] < a[m][0]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

// Shortest axis-parallel path on the Hanan grid of obstacle edges, avoiding
// the open interiors of all obstacles. `stages` is a list of candidate point
// lists: the path visits one point from each stage, in order.
function gridRoute(stages, obstacles) {
  const all = stages.flat();
  let mnx = Infinity;
  let mny = Infinity;
  let mxx = -Infinity;
  let mxy = -Infinity;
  const grow = (x, y) => {
    mnx = Math.min(mnx, x);
    mny = Math.min(mny, y);
    mxx = Math.max(mxx, x);
    mxy = Math.max(mxy, y);
  };
  for (const o of obstacles) {
    grow(o.x, o.y);
    grow(o.x + o.width, o.y + o.height);
  }
  for (const p of all) grow(p[0], p[1]);
  if (!Number.isFinite(mnx)) return null;

  const xset = new Set();
  const yset = new Set();
  for (const o of obstacles) {
    xset.add(r6(o.x));
    xset.add(r6(o.x + o.width));
    yset.add(r6(o.y));
    yset.add(r6(o.y + o.height));
  }
  for (const p of all) {
    xset.add(r6(p[0]));
    yset.add(r6(p[1]));
  }
  xset.add(r6(mnx - MARGIN));
  xset.add(r6(mxx + MARGIN));
  yset.add(r6(mny - MARGIN));
  yset.add(r6(mxy + MARGIN));
  const xs = [...xset].sort((a, b) => a - b);
  const ys = [...yset].sort((a, b) => a - b);
  const nx = xs.length;
  const ny = ys.length;
  const xi = new Map(xs.map((v, i) => [v, i]));
  const yi = new Map(ys.map((v, i) => [v, i]));
  const idx = (p) => xi.get(r6(p[0])) * ny + yi.get(r6(p[1]));

  const blockedH = (y, a, b) =>
    obstacles.some((o) => y > o.y && y < o.y + o.height && Math.max(a, o.x) < Math.min(b, o.x + o.width));
  const blockedV = (x, a, b) =>
    obstacles.some((o) => x > o.x && x < o.x + o.width && Math.max(a, o.y) < Math.min(b, o.y + o.height));

  const DX = [1, -1, 0, 0];
  const DY = [0, 0, 1, -1];
  const OPP = [1, 0, 3, 2];

  const search = (starts, goals) => {
    const S = nx * ny * 5;
    const dist = new Float64Array(S).fill(Infinity);
    const prev = new Int32Array(S).fill(-1);
    const heap = new MinHeap();
    for (const n of starts) {
      const st = n * 5 + 4;
      dist[st] = 0;
      heap.push(0, st);
    }
    while (heap.size > 0) {
      const [d, st] = heap.pop();
      if (d > dist[st]) continue;
      const node = (st - (st % 5)) / 5;
      const dir = st % 5;
      if (goals.has(node)) {
        const nodes = [];
        for (let s = st; s !== -1; s = prev[s]) nodes.push((s - (s % 5)) / 5);
        return nodes.reverse();
      }
      const i = Math.floor(node / ny);
      const j = node - i * ny;
      for (let nd = 0; nd < 4; nd++) {
        if (dir < 4 && nd === OPP[dir]) continue;
        const ni = i + DX[nd];
        const nj = j + DY[nd];
        if (ni < 0 || nj < 0 || ni >= nx || nj >= ny) continue;
        const x1 = xs[i];
        const y1 = ys[j];
        const x2 = xs[ni];
        const y2 = ys[nj];
        const blocked =
          nd < 2
            ? blockedH(y1, Math.min(x1, x2), Math.max(x1, x2))
            : blockedV(x1, Math.min(y1, y2), Math.max(y1, y2));
        if (blocked) continue;
        const nst = (ni * ny + nj) * 5 + nd;
        const cost =
          d + Math.abs(x2 - x1) + Math.abs(y2 - y1) + (dir < 4 && dir !== nd ? BEND_PENALTY : 0);
        if (cost < dist[nst]) {
          dist[nst] = cost;
          prev[nst] = st;
          heap.push(cost, nst);
        }
      }
    }
    return null;
  };

  let current = stages[0].map(idx);
  let full = null;
  for (let k = 1; k < stages.length; k++) {
    const goals = new Set(stages[k].map(idx));
    const seg = search(current, goals);
    if (!seg) return null;
    full = full ? full.concat(seg.slice(1)) : seg;
    current = [seg[seg.length - 1]];
  }
  if (!full) full = [current[0]];
  return full.map((n) => [xs[Math.floor(n / ny)], ys[n % ny]]);
}

function endpointPoint(ref, el, toward) {
  if (!el) return ref && ref.point ? toPoint(ref.point) : [0, 0];
  if (ref && ref.port) {
    const a = sideAnchor(el, ref.port);
    if (a) return a;
  }
  return boundaryToward(el, toward);
}

function refCenter(ref, el) {
  if (el) return centerOf(el);
  return ref && ref.point ? toPoint(ref.point) : [0, 0];
}

function candidates(ref, el) {
  if (!el) return [ref && ref.point ? toPoint(ref.point) : [0, 0]];
  if (ref && ref.port) {
    const a = sideAnchor(el, ref.port);
    if (a) return [a];
  }
  return ['top', 'right', 'bottom', 'left'].map((s) => sideAnchor(el, s));
}

// Compute the polyline for a connector. `lookup(id)` returns an element, `shapes`
// is the list of shapes used as obstacles.
export function computeRoute(conn, lookup, shapes) {
  const srcId = conn.source ? conn.source.elementId : null;
  const tgtId = conn.target ? conn.target.elementId : null;
  const srcEl = srcId != null ? lookup(srcId) : undefined;
  const tgtEl = tgtId != null ? lookup(tgtId) : undefined;
  const sEl = srcEl && srcEl.type !== 'connector' ? srcEl : undefined;
  const tEl = tgtEl && tgtEl.type !== 'connector' ? tgtEl : undefined;
  const wps = (conn.waypoints || []).map(toPoint);

  if (conn.routing === 'orthogonal') {
    const stages = [candidates(conn.source, sEl), ...wps.map((p) => [p]), candidates(conn.target, tEl)];
    const path = gridRoute(stages, shapes.map(aabbOf));
    if (path) return dedupeAndSimplify(path);
    const s = stages[0][0];
    const t = stages[stages.length - 1][0];
    return dedupeAndSimplify([s, [t[0], s[1]], t]);
  }

  const sRef = conn.source || {};
  const tRef = conn.target || {};
  const sToward = wps.length ? wps[0] : refCenter(tRef, tEl);
  const tToward = wps.length ? wps[wps.length - 1] : refCenter(sRef, sEl);
  const s = endpointPoint(sRef, sEl, sToward);
  const t = endpointPoint(tRef, tEl, tToward);
  return dedupeAndSimplify([s, ...wps, t]);
}

