// Minimal parser for uncompressed draw.io (mxGraph) XML. No DOM required.
const ATTR = /([^\s=/>"']+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
const TAG = /<(\/?)([A-Za-z][\w.:-]*)([^>]*?)(\/?)>/g;

export function decodeEntities(s) {
  return String(s).replace(/&(#x[0-9a-fA-F]+|#\d+|lt|gt|amp|quot|apos|nbsp);/g, (m, e) => {
    if (e[0] === '#') {
      const code = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return String.fromCodePoint(code);
    }
    return { lt: '<', gt: '>', amp: '&', quot: '"', apos: "'", nbsp: ' ' }[e];
  });
}

function parseAttrs(text) {
  const out = {};
  for (const m of text.matchAll(ATTR)) out[m[1]] = decodeEntities(m[2] ?? m[3] ?? '');
  return out;
}

const num = (v) => (v === undefined || !Number.isFinite(Number(v)) ? 0 : Number(v));

// Returns a flat list of mxCell records.
export function parseDrawio(xml) {
  const src = String(xml).replace(/<!--[\s\S]*?-->/g, '');
  const cells = [];
  let cell = null;
  let inArray = false;
  let pendingObj = null;
  for (const m of src.matchAll(TAG)) {
    const [, close, name, rest, selfClose] = m;
    if (close) {
      if (name === 'mxCell') {
        if (cell) cells.push(cell);
        cell = null;
      } else if (name === 'Array') {
        inArray = false;
      } else if (name === 'object' || name === 'UserObject') {
        pendingObj = null;
      }
      continue;
    }
    const a = parseAttrs(rest);
    if (name === 'object' || name === 'UserObject') {
      if (!selfClose) pendingObj = a;
      continue;
    }
    if (name === 'mxCell') {
      const meta = pendingObj ?? {};
      cell = {
        id: a.id ?? meta.id,
        value: a.value ?? meta.label ?? '',
        style: a.style ?? '',
        vertex: a.vertex === '1',
        edge: a.edge === '1',
        parent: a.parent ?? null,
        source: a.source ?? null,
        target: a.target ?? null,
        geometry: null,
        waypoints: [],
        sourcePoint: null,
        targetPoint: null,
      };
      if (selfClose) {
        cells.push(cell);
        cell = null;
      }
      continue;
    }
    if (!cell) continue;
    if (name === 'mxGeometry') {
      cell.geometry = { x: num(a.x), y: num(a.y), width: num(a.width), height: num(a.height) };
      continue;
    }
    if (name === 'Array') {
      if (!selfClose) inArray = true;
      continue;
    }
    if (name === 'mxPoint' && (a.x !== undefined || a.y !== undefined)) {
      const p = { x: num(a.x), y: num(a.y) };
      if (a.as === 'sourcePoint') cell.sourcePoint = p;
      else if (a.as === 'targetPoint') cell.targetPoint = p;
      else if (inArray) cell.waypoints.push(p);
    }
  }
  return cells;
}

export function parseStyle(str) {
  const map = {};
  const bare = new Set();
  for (const tok of String(str ?? '').split(';')) {
    const t = tok.trim();
    if (!t) continue;
    const eq = t.indexOf('=');
    if (eq < 0) bare.add(t);
    else map[t.slice(0, eq)] = t.slice(eq + 1);
  }
  return { map, bare };
}

