const esc = (s) =>
  String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);

function textSvg(text, cx, cy, style, color) {
  const lines = String(text).split('\n');
  const size = num(style.fontSize ?? 14);
  const family = style.fontFamily ? ` font-family="${esc(style.fontFamily)}"` : '';
  const fill = color ?? style.fontColor ?? '#000000';
  const spans = lines
    .map((l, i) => `<tspan x="${num(cx)}" dy="${i === 0 ? 0 : '1.2em'}">${esc(l)}</tspan>`)
    .join('');
  return `<text x="${num(cx)}" y="${num(cy)}" text-anchor="middle" dominant-baseline="middle" font-size="${size}" fill="${esc(fill)}"${family}>${spans}</text>`;
}

function shapeStyle(style) {
  const fill = style.fill ?? '#ffffff';
  const stroke = style.stroke ?? '#000000';
  const sw = num(style.strokeWidth ?? 1);
  const op = style.opacity !== undefined ? ` opacity="${num(style.opacity)}"` : '';
  return ` fill="${esc(fill)}" stroke="${esc(stroke)}" stroke-width="${sw}"${op}`;
}

function renderItem({ el, route }) {
  const id = esc(el.id);
  const style = el.style || {};
  if (el.type === 'connector') {
    const pts = (route || []).map((p) => `${num(p[0])},${num(p[1])}`).join(' ');
    const body = `<polyline points="${pts}" fill="none" stroke="${esc(style.stroke ?? '#000000')}" stroke-width="${num(style.strokeWidth ?? 1)}"/>`;
    let label = '';
    if (el.label && route && route.length) {
      const a = route[Math.floor((route.length - 1) / 2)];
      const b = route[Math.ceil((route.length - 1) / 2)];
      label = textSvg(el.label, (a[0] + b[0]) / 2, (a[1] + b[1]) / 2, style);
    }
    return `<g data-id="${id}" data-type="connector">${body}${label}</g>`;
  }
  const { x, y, width: w, height: h } = el;
  const cx = x + w / 2;
  const cy = y + h / 2;
  const tf = el.rotation ? ` transform="rotate(${num(el.rotation)} ${cx} ${cy})"` : '';
  let shape = '';
  let label = '';
  switch (el.type) {
    case 'rect':
      shape = `<rect x="${num(x)}" y="${num(y)}" width="${num(w)}" height="${num(h)}"${shapeStyle(style)}/>`;
      break;
    case 'ellipse':
      shape = `<ellipse cx="${num(cx)}" cy="${num(cy)}" rx="${num(w / 2)}" ry="${num(h / 2)}"${shapeStyle(style)}/>`;
      break;
    case 'diamond': {
      const pts = [
        [x + w / 2, y],
        [x + w, y + h / 2],
        [x + w / 2, y + h],
        [x, y + h / 2],
      ].map((p) => `${num(p[0])},${num(p[1])}`).join(' ');
      shape = `<polygon points="${pts}"${shapeStyle(style)}/>`;
      break;
    }
    case 'line':
      shape = `<line x1="${num(x)}" y1="${num(y)}" x2="${num(x + w)}" y2="${num(y + h)}" stroke="${esc(style.stroke ?? '#000000')}" stroke-width="${num(style.strokeWidth ?? 1)}"/>`;
      break;
    case 'image':
      shape = `<image href="${esc(el.text)}" x="${num(x)}" y="${num(y)}" width="${num(w)}" height="${num(h)}" preserveAspectRatio="none"/>`;
      break;
    default:
      break;
  }
  if (el.type === 'text' && el.text) label = textSvg(el.text, cx, cy, style, style.fontColor ?? '#000000');
  else if (el.type !== 'image' && el.text) label = textSvg(el.text, cx, cy, style);
  return `<g data-id="${id}" data-type="${esc(el.type)}"${tf}>${shape}${label}</g>`;
}

export function renderSVG(items, padding = 10) {
  const boxes = [];
  for (const it of items) {
    if (it.el.type === 'connector') {
      for (const p of it.route || []) boxes.push({ x: p[0], y: p[1], width: 0, height: 0 });
    } else {
      boxes.push(aabbOf(it.el));
    }
  }
  const b = boxes.length ? unionBox(boxes) : { x: 0, y: 0, width: 0, height: 0 };
  const x = b.x - padding;
  const y = b.y - padding;
  const w = Math.max(1, b.width + 2 * padding);
  const h = Math.max(1, b.height + 2 * padding);
  const body = items.map(renderItem).join('\n');
  return `<?xml version="1.0" encoding="UTF-8"?>\n<svg xmlns="http://www.w3.org/2000/svg" viewBox="${num(x)} ${num(y)} ${num(w)} ${num(h)}" width="${num(w)}" height="${num(h)}">\n${body}\n</svg>\n`;
}

