// Error type used by every core operation that rejects its input.
export class DiagramError extends Error {
  constructor(message) {
    super(message);
    this.name = 'DiagramError';
  }
}

// Geometry helpers, snapping and connector routing (straight and orthogonal).
const DEG = Math.PI / 180;
const MARGIN = 100;
const BEND_PENALTY = 40;

const r6 = (v) => Math.round(v * 1e6) / 1e6;

export function toPoint(p) {
  return Array.isArray(p) ? [Number(p[0]), Number(p[1])] : [Number(p.x), Number(p.y)];
}

export function rotatePoint(px, py, cx, cy, deg) {
  const a = deg * DEG;
  const c = Math.cos(a);
  const s = Math.sin(a);
  const dx = px - cx;
  const dy = py - cy;
  return [cx + dx * c - dy * s, cy + dx * s + dy * c];
}

export function centerOf(el) {
  return [el.x + el.width / 2, el.y + el.height / 2];
}

// Axis-aligned bounding box of a (possibly rotated) shape.
export function aabbOf(el) {
  const [cx, cy] = centerOf(el);
  const rot = el.rotation || 0;
  const corners = [
    [el.x, el.y],
    [el.x + el.width, el.y],
    [el.x + el.width, el.y + el.height],
    [el.x, el.y + el.height],
  ].map(([x, y]) => rotatePoint(x, y, cx, cy, rot));
  const xs = corners.map((p) => p[0]);
  const ys = corners.map((p) => p[1]);
  const x = Math.min(...xs);
  const y = Math.min(...ys);
  return { x, y, width: Math.max(...xs) - x, height: Math.max(...ys) - y };
}

export function unionBox(boxes) {
  let x0 = Infinity;
  let y0 = Infinity;
  let x1 = -Infinity;
  let y1 = -Infinity;
  for (const b of boxes) {
    x0 = Math.min(x0, b.x);
    y0 = Math.min(y0, b.y);
    x1 = Math.max(x1, b.x + b.width);
    y1 = Math.max(y1, b.y + b.height);
  }
  return { x: x0, y: y0, width: x1 - x0, height: y1 - y0 };
}

// Rotation-aware containment test for the shape's outline.
export function containsPoint(el, px, py) {
  const [cx, cy] = centerOf(el);
  const [lx, ly] = rotatePoint(px, py, cx, cy, -(el.rotation || 0));
  const hw = el.width / 2;
  const hh = el.height / 2;
  const dx = lx - cx;
  const dy = ly - cy;
  if (el.type === 'ellipse' && hw > 0 && hh > 0) {
    return (dx * dx) / (hw * hw) + (dy * dy) / (hh * hh) <= 1;
  }
  if (el.type === 'diamond' && hw > 0 && hh > 0) {
    return Math.abs(dx) / hw + Math.abs(dy) / hh <= 1;
  }
  return Math.abs(dx) <= hw && Math.abs(dy) <= hh;
}

// Point where the segment from the element centre towards `toward` leaves the outline.
export function boundaryToward(el, toward) {
  const [cx, cy] = centerOf(el);
  const [tx, ty] = toward;
  const inside = (t) => containsPoint(el, cx + (tx - cx) * t, cy + (ty - cy) * t);
  if (!inside(0)) return [cx, cy];
  if (inside(1)) return [tx, ty];
  let lo = 0;
  let hi = 1;
  for (let i = 0; i < 50; i++) {
    const m = (lo + hi) / 2;
    if (inside(m)) lo = m;
    else hi = m;
  }
  return [cx + (tx - cx) * lo, cy + (ty - cy) * lo];
}

// Midpoint of a side, rotated with the element. Returns null for unknown sides.
export function sideAnchor(el, side) {
  const { x, y, width: w, height: h } = el;
  const pts = {
    top: [x + w / 2, y],
    bottom: [x + w / 2, y + h],
    left: [x, y + h / 2],
    right: [x + w, y + h / 2],
  };
  const p = pts[side];
  if (!p) return null;
  const [cx, cy] = centerOf(el);
  return rotatePoint(p[0], p[1], cx, cy, el.rotation || 0);
}

// Snap a point ({x,y} or [x,y]) to guides within tolerance, otherwise to the grid.
export function snap(point, opts = {}) {
  const { grid, guides, tolerance = 5 } = opts;
  const isArr = Array.isArray(point);
  const x0 = isArr ? Number(point[0]) : Number(point.x);
  const y0 = isArr ? Number(point[1]) : Number(point.y);
  const xs = [];
  const ys = [];
  if (guides && !Array.isArray(guides) && typeof guides === 'object') {
    xs.push(...(guides.x || []));
    ys.push(...(guides.y || []));
  } else if (Array.isArray(guides)) {
    for (const g of guides) {
      if (Array.isArray(g)) {
        xs.push(g[0]);
        ys.push(g[1]);
      } else if (g && typeof g === 'object') {
        if (g.x !== undefined) xs.push(g.x);
        if (g.y !== undefined) ys.push(g.y);
      }
    }
  }
  const pick = (v, step, lines) => {
    let best = null;
    let bd = tolerance;
    for (const t of lines) {
      const d = Math.abs(t - v);
      if (d <= bd) {
        bd = d;
        best = t;
      }
    }
    if (best !== null) return best;
    return step ? Math.round(v / step) * step : v;
  };
  const x = pick(x0, grid, xs);
  const y = pick(y0, grid, ys);
  return isArr ? [x, y] : { x, y };
}

function dedupeAndSimplify(pts) {
  const out = [];
  for (const p of pts) {
    const q = [r6(p[0]), r6(p[1])];
    const last = out[out.length - 1];
    if (last && last[0] === q[0] && last[1] === q[1]) continue;
    out.push(q);
  }
  const res = [];
  for (let i = 0; i < out.length; i++) {
    if (i > 0 && i < out.length - 1) {
      const a = out[i - 1];
      const b = out[i];
      const c = out[i + 1];
      if ((a[0] === b[0] && b[0] === c[0]) || (a[1] === b[1] && b[1] === c[1])) continue;
    }
    res.push(out[i]);
  }
  return res;
}

class MinHeap {
  constructor() {
    this.a = [];
  }

  get size() {
    return this.a.length;
  }

  push(k, v) {
    const a = this.a;
    a.push([k, v]);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p][0] <= a[i][0]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }

  pop() {
    const a = this.a;
    const top = a[0];
    const last = a.pop();
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let m = i;
        if (l < a.length && a[l][0] < a[m][0]) m = l;
        if (r < a.length && a[r][0] < a[m][0]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

// Shortest axis-parallel path on the Hanan grid of obstacle edges, avoiding
// the open interiors of all obstacles. `stages` is a list of candidate point
// lists: the path visits one point from each stage, in order.
function gridRoute(stages, obstacles) {
  const all = stages.flat();
  let mnx = Infinity;
  let mny = Infinity;
  let mxx = -Infinity;
  let mxy = -Infinity;
  const grow = (x, y) => {
    mnx = Math.min(mnx, x);
    mny = Math.min(mny, y);
    mxx = Math.max(mxx, x);
    mxy = Math.max(mxy, y);
  };
  for (const o of obstacles) {
    grow(o.x, o.y);
    grow(o.x + o.width, o.y + o.height);
  }
  for (const p of all) grow(p[0], p[1]);
  if (!Number.isFinite(mnx)) return null;

  const xset = new Set();
  const yset = new Set();
  for (const o of obstacles) {
    xset.add(r6(o.x));
    xset.add(r6(o.x + o.width));
    yset.add(r6(o.y));
    yset.add(r6(o.y + o.height));
  }
  for (const p of all) {
    xset.add(r6(p[0]));
    yset.add(r6(p[1]));
  }
  xset.add(r6(mnx - MARGIN));
  xset.add(r6(mxx + MARGIN));
  yset.add(r6(mny - MARGIN));
  yset.add(r6(mxy + MARGIN));
  const xs = [...xset].sort((a, b) => a - b);
  const ys = [...yset].sort((a, b) => a - b);
  const nx = xs.length;
  const ny = ys.length;
  const xi = new Map(xs.map((v, i) => [v, i]));
  const yi = new Map(ys.map((v, i) => [v, i]));
  const idx = (p) => xi.get(r6(p[0])) * ny + yi.get(r6(p[1]));

  const blockedH = (y, a, b) =>
    obstacles.some((o) => y > o.y && y < o.y + o.height && Math.max(a, o.x) < Math.min(b, o.x + o.width));
  const blockedV = (x, a, b) =>
    obstacles.some((o) => x > o.x && x < o.x + o.width && Math.max(a, o.y) < Math.min(b, o.y + o.height));

  const DX = [1, -1, 0, 0];
  const DY = [0, 0, 1, -1];
  const OPP = [1, 0, 3, 2];

  const search = (starts, goals) => {
    const S = nx * ny * 5;
    const dist = new Float64Array(S).fill(Infinity);
    const prev = new Int32Array(S).fill(-1);
    const heap = new MinHeap();
    for (const n of starts) {
      const st = n * 5 + 4;
      dist[st] = 0;
      heap.push(0, st);
    }
    while (heap.size > 0) {
      const [d, st] = heap.pop();
      if (d > dist[st]) continue;
      const node = (st - (st % 5)) / 5;
      const dir = st % 5;
      if (goals.has(node)) {
        const nodes = [];
        for (let s = st; s !== -1; s = prev[s]) nodes.push((s - (s % 5)) / 5);
        return nodes.reverse();
      }
      const i = Math.floor(node / ny);
      const j = node - i * ny;
      for (let nd = 0; nd < 4; nd++) {
        if (dir < 4 && nd === OPP[dir]) continue;
        const ni = i + DX[nd];
        const nj = j + DY[nd];
        if (ni < 0 || nj < 0 || ni >= nx || nj >= ny) continue;
        const x1 = xs[i];
        const y1 = ys[j];
        const x2 = xs[ni];
        const y2 = ys[nj];
        const blocked =
          nd < 2
            ? blockedH(y1, Math.min(x1, x2), Math.max(x1, x2))
            : blockedV(x1, Math.min(y1, y2), Math.max(y1, y2));
        if (blocked) continue;
        const nst = (ni * ny + nj) * 5 + nd;
        const cost =
          d + Math.abs(x2 - x1) + Math.abs(y2 - y1) + (dir < 4 && dir !== nd ? BEND_PENALTY : 0);
        if (cost < dist[nst]) {
          dist[nst] = cost;
          prev[nst] = st;
          heap.push(cost, nst);
        }
      }
    }
    return null;
  };

  let current = stages[0].map(idx);
  let full = null;
  for (let k = 1; k < stages.length; k++) {
    const goals = new Set(stages[k].map(idx));
    const seg = search(current, goals);
    if (!seg) return null;
    full = full ? full.concat(seg.slice(1)) : seg;
    current = [seg[seg.length - 1]];
  }
  if (!full) full = [current[0]];
  return full.map((n) => [xs[Math.floor(n / ny)], ys[n % ny]]);
}

function endpointPoint(ref, el, toward) {
  if (!el) return ref && ref.point ? toPoint(ref.point) : [0, 0];
  if (ref && ref.port) {
    const a = sideAnchor(el, ref.port);
    if (a) return a;
  }
  return boundaryToward(el, toward);
}

function refCenter(ref, el) {
  if (el) return centerOf(el);
  return ref && ref.point ? toPoint(ref.point) : [0, 0];
}

function candidates(ref, el) {
  if (!el) return [ref && ref.point ? toPoint(ref.point) : [0, 0]];
  if (ref && ref.port) {
    const a = sideAnchor(el, ref.port);
    if (a) return [a];
  }
  return ['top', 'right', 'bottom', 'left'].map((s) => sideAnchor(el, s));
}

// Compute the polyline for a connector. `lookup(id)` returns an element, `shapes`
// is the list of shapes used as obstacles.
export function computeRoute(conn, lookup, shapes) {
  const srcId = conn.source ? conn.source.elementId : null;
  const tgtId = conn.target ? conn.target.elementId : null;
  const srcEl = srcId != null ? lookup(srcId) : undefined;
  const tgtEl = tgtId != null ? lookup(tgtId) : undefined;
  const sEl = srcEl && srcEl.type !== 'connector' ? srcEl : undefined;
  const tEl = tgtEl && tgtEl.type !== 'connector' ? tgtEl : undefined;
  const wps = (conn.waypoints || []).map(toPoint);

  if (conn.routing === 'orthogonal') {
    const stages = [candidates(conn.source, sEl), ...wps.map((p) => [p]), candidates(conn.target, tEl)];
    const path = gridRoute(stages, shapes.map(aabbOf));
    if (path) return dedupeAndSimplify(path);
    const s = stages[0][0];
    const t = stages[stages.length - 1][0];
    return dedupeAndSimplify([s, [t[0], s[1]], t]);
  }

  const sRef = conn.source || {};
  const tRef = conn.target || {};
  const sToward = wps.length ? wps[0] : refCenter(tRef, tEl);
  const tToward = wps.length ? wps[wps.length - 1] : refCenter(sRef, sEl);
  const s = endpointPoint(sRef, sEl, sToward);
  const t = endpointPoint(tRef, tEl, tToward);
  return dedupeAndSimplify([s, ...wps, t]);
}

// Auto-layout: layered (Sugiyama-style) and grid. Both return Map(id -> {x, y}).

function sortByBarycenter(row, neighbourPositions) {
  return row
    .map((n, k) => {
      const ps = neighbourPositions(n);
      const b = ps.length ? ps.reduce((a, c) => a + c, 0) / ps.length : k;
      return { n, b, k };
    })
    .sort((p, q) => p.b - q.b || p.k - q.k)
    .map((o) => o.n);
}

export function layeredPositions(nodes, edges, { direction = 'TB', spacing = 40 } = {}) {
  const N = nodes.length;
  const idx = new Map(nodes.map((n, i) => [n.id, i]));
  const E = [];
  for (const e of edges) {
    const u = idx.get(e.from);
    const v = idx.get(e.to);
    if (u === undefined || v === undefined || u === v) continue;
    E.push([u, v]);
  }

  // Cycle breaking: reverse back edges found by DFS.
  const out = Array.from({ length: N }, () => []);
  E.forEach(([u], k) => out[u].push(k));
  const color = new Array(N).fill(0);
  const reversed = new Array(E.length).fill(false);
  const dfs = (u) => {
    color[u] = 1;
    for (const k of out[u]) {
      const v = E[k][1];
      if (color[v] === 1) reversed[k] = true;
      else if (color[v] === 0) dfs(v);
    }
    color[u] = 2;
  };
  for (let u = 0; u < N; u++) if (color[u] === 0) dfs(u);

  const dag = E.map(([u, v], k) => (reversed[k] ? [v, u] : [u, v]));
  const succ = Array.from({ length: N }, () => []);
  const pred = Array.from({ length: N }, () => []);
  const indeg = new Array(N).fill(0);
  for (const [u, v] of dag) {
    succ[u].push(v);
    pred[v].push(u);
    indeg[v]++;
  }

  // Longest-path ranking.
  const rank = new Array(N).fill(0);
  const queue = [];
  for (let u = 0; u < N; u++) if (indeg[u] === 0) queue.push(u);
  for (let qi = 0; qi < queue.length; qi++) {
    const u = queue[qi];
    for (const v of succ[u]) {
      rank[v] = Math.max(rank[v], rank[u] + 1);
      if (--indeg[v] === 0) queue.push(v);
    }
  }
  const R = N ? Math.max(...rank) + 1 : 0;
  const order = Array.from({ length: R }, () => []);
  for (let u = 0; u < N; u++) order[rank[u]].push(u);

  const crossings = (ord) => {
    const pos = new Array(N);
    ord.forEach((row) => row.forEach((n, k) => (pos[n] = k)));
    const between = [];
    for (const [u, v] of dag) {
      if (rank[v] === rank[u] + 1) between.push([pos[u], pos[v], rank[u]]);
    }
    let c = 0;
    for (let a = 0; a < between.length; a++) {
      for (let b = a + 1; b < between.length; b++) {
        const p = between[a];
        const q = between[b];
        if (p[2] !== q[2]) continue;
        if ((p[0] - q[0]) * (p[1] - q[1]) < 0) c++;
      }
    }
    return c;
  };

  // The input order is a candidate, so the result never has more crossings than it.
  let best = order.map((r) => r.slice());
  let bestC = crossings(best);
  const cur = order.map((r) => r.slice());
  const posOf = () => {
    const pos = new Array(N);
    cur.forEach((row) => row.forEach((n, k) => (pos[n] = k)));
    return pos;
  };
  for (let it = 0; it < 10 && bestC > 0; it++) {
    for (let r = 1; r < R; r++) {
      const pos = posOf();
      cur[r] = sortByBarycenter(cur[r], (n) => pred[n].filter((u) => rank[u] === r - 1).map((u) => pos[u]));
    }
    for (let r = R - 2; r >= 0; r--) {
      const pos = posOf();
      cur[r] = sortByBarycenter(cur[r], (n) => succ[n].filter((v) => rank[v] === r + 1).map((v) => pos[v]));
    }
    const c = crossings(cur);
    if (c < bestC) {
      bestC = c;
      best = cur.map((r) => r.slice());
    }
  }

  const horiz = direction === 'LR';
  const main = horiz ? 'width' : 'height';
  const cross = horiz ? 'height' : 'width';
  const thick = best.map((row) => row.reduce((m, n) => Math.max(m, nodes[n][main]), 0));
  const totals = best.map(
    (row) => row.reduce((s, n) => s + nodes[n][cross], 0) + spacing * Math.max(0, row.length - 1),
  );
  const maxTotal = Math.max(0, ...totals);
  const pos = new Map();
  let mainPos = 0;
  best.forEach((row, r) => {
    let c = (maxTotal - totals[r]) / 2;
    for (const n of row) {
      const node = nodes[n];
      const m = mainPos + (thick[r] - node[main]) / 2;
      pos.set(node.id, horiz ? { x: m, y: c } : { x: c, y: m });
      c += node[cross] + spacing;
    }
    mainPos += thick[r] + spacing;
  });
  return pos;
}

export function gridPositions(nodes, { spacing = 40 } = {}) {
  const pos = new Map();
  const cols = Math.max(1, Math.ceil(Math.sqrt(nodes.length)));
  const cw = Math.max(0, ...nodes.map((n) => n.width)) + spacing;
  const ch = Math.max(0, ...nodes.map((n) => n.height)) + spacing;
  nodes.forEach((n, i) => pos.set(n.id, { x: (i % cols) * cw, y: Math.floor(i / cols) * ch }));
  return pos;
}

// Minimal parser for uncompressed draw.io (mxGraph) XML. No DOM required.
const ATTR = /([^\s=/>"']+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
const TAG = /<(\/?)([A-Za-z][\w.:-]*)([^>]*?)(\/?)>/g;

export function decodeEntities(s) {
  return String(s).replace(/&(#x[0-9a-fA-F]+|#\d+|lt|gt|amp|quot|apos|nbsp);/g, (m, e) => {
    if (e[0] === '#') {
      const code = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return String.fromCodePoint(code);
    }
    return { lt: '<', gt: '>', amp: '&', quot: '"', apos: "'", nbsp: ' ' }[e];
  });
}

function parseAttrs(text) {
  const out = {};
  for (const m of text.matchAll(ATTR)) out[m[1]] = decodeEntities(m[2] ?? m[3] ?? '');
  return out;
}

const num = (v) => (v === undefined || !Number.isFinite(Number(v)) ? 0 : Number(v));

// Returns a flat list of mxCell records.
export function parseDrawio(xml) {
  const src = String(xml).replace(/<!--[\s\S]*?-->/g, '');
  const cells = [];
  let cell = null;
  let inArray = false;
  let pendingObj = null;
  for (const m of src.matchAll(TAG)) {
    const [, close, name, rest, selfClose] = m;
    if (close) {
      if (name === 'mxCell') {
        if (cell) cells.push(cell);
        cell = null;
      } else if (name === 'Array') {
        inArray = false;
      } else if (name === 'object' || name === 'UserObject') {
        pendingObj = null;
      }
      continue;
    }
    const a = parseAttrs(rest);
    if (name === 'object' || name === 'UserObject') {
      if (!selfClose) pendingObj = a;
      continue;
    }
    if (name === 'mxCell') {
      const meta = pendingObj ?? {};
      cell = {
        id: a.id ?? meta.id,
        value: a.value ?? meta.label ?? '',
        style: a.style ?? '',
        vertex: a.vertex === '1',
        edge: a.edge === '1',
        parent: a.parent ?? null,
        source: a.source ?? null,
        target: a.target ?? null,
        geometry: null,
        waypoints: [],
        sourcePoint: null,
        targetPoint: null,
      };
      if (selfClose) {
        cells.push(cell);
        cell = null;
      }
      continue;
    }
    if (!cell) continue;
    if (name === 'mxGeometry') {
      cell.geometry = { x: num(a.x), y: num(a.y), width: num(a.width), height: num(a.height) };
      continue;
    }
    if (name === 'Array') {
      if (!selfClose) inArray = true;
      continue;
    }
    if (name === 'mxPoint' && (a.x !== undefined || a.y !== undefined)) {
      const p = { x: num(a.x), y: num(a.y) };
      if (a.as === 'sourcePoint') cell.sourcePoint = p;
      else if (a.as === 'targetPoint') cell.targetPoint = p;
      else if (inArray) cell.waypoints.push(p);
    }
  }
  return cells;
}

export function parseStyle(str) {
  const map = {};
  const bare = new Set();
  for (const tok of String(str ?? '').split(';')) {
    const t = tok.trim();
    if (!t) continue;
    const eq = t.indexOf('=');
    if (eq < 0) bare.add(t);
    else map[t.slice(0, eq)] = t.slice(eq + 1);
  }
  return { map, bare };
}

// SVG rendering for a list of visible items: [{ el, route }] in back-to-front order.
import { aabbOf, unionBox } from './geometry.js';

const esc = (s) =>
  String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);

function textSvg(text, cx, cy, style, color) {
  const lines = String(text).split('\n');
  const size = num(style.fontSize ?? 14);
  const family = style.fontFamily ? ` font-family="${esc(style.fontFamily)}"` : '';
  const fill = color ?? style.fontColor ?? '#000000';
  const spans = lines
    .map((l, i) => `<tspan x="${num(cx)}" dy="${i === 0 ? 0 : '1.2em'}">${esc(l)}</tspan>`)
    .join('');
  return `<text x="${num(cx)}" y="${num(cy)}" text-anchor="middle" dominant-baseline="middle" font-size="${size}" fill="${esc(fill)}"${family}>${spans}</text>`;
}

function shapeStyle(style) {
  const fill = style.fill ?? '#ffffff';
  const stroke = style.stroke ?? '#000000';
  const sw = num(style.strokeWidth ?? 1);
  const op = style.opacity !== undefined ? ` opacity="${num(style.opacity)}"` : '';
  return ` fill="${esc(fill)}" stroke="${esc(stroke)}" stroke-width="${sw}"${op}`;
}

function renderItem({ el, route }) {
  const id = esc(el.id);
  const style = el.style || {};
  if (el.type === 'connector') {
    const pts = (route || []).map((p) => `${num(p[0])},${num(p[1])}`).join(' ');
    const body = `<polyline points="${pts}" fill="none" stroke="${esc(style.stroke ?? '#000000')}" stroke-width="${num(style.strokeWidth ?? 1)}"/>`;
    let label = '';
    if (el.label && route && route.length) {
      const a = route[Math.floor((route.length - 1) / 2)];
      const b = route[Math.ceil((route.length - 1) / 2)];
      label = textSvg(el.label, (a[0] + b[0]) / 2, (a[1] + b[1]) / 2, style);
    }
    return `<g data-id="${id}" data-type="connector">${body}${label}</g>`;
  }
  const { x, y, width: w, height: h } = el;
  const cx = x + w / 2;
  const cy = y + h / 2;
  const tf = el.rotation ? ` transform="rotate(${num(el.rotation)} ${cx} ${cy})"` : '';
  let shape = '';
  let label = '';
  switch (el.type) {
    case 'rect':
      shape = `<rect x="${num(x)}" y="${num(y)}" width="${num(w)}" height="${num(h)}"${shapeStyle(style)}/>`;
      break;
    case 'ellipse':
      shape = `<ellipse cx="${num(cx)}" cy="${num(cy)}" rx="${num(w / 2)}" ry="${num(h / 2)}"${shapeStyle(style)}/>`;
      break;
    case 'diamond': {
      const pts = [
        [x + w / 2, y],
        [x + w, y + h / 2],
        [x + w / 2, y + h],
        [x, y + h / 2],
      ].map((p) => `${num(p[0])},${num(p[1])}`).join(' ');
      shape = `<polygon points="${pts}"${shapeStyle(style)}/>`;
      break;
    }
    case 'line':
      shape = `<line x1="${num(x)}" y1="${num(y)}" x2="${num(x + w)}" y2="${num(y + h)}" stroke="${esc(style.stroke ?? '#000000')}" stroke-width="${num(style.strokeWidth ?? 1)}"/>`;
      break;
    case 'image':
      shape = `<image href="${esc(el.text)}" x="${num(x)}" y="${num(y)}" width="${num(w)}" height="${num(h)}" preserveAspectRatio="none"/>`;
      break;
    default:
      break;
  }
  if (el.type === 'text' && el.text) label = textSvg(el.text, cx, cy, style, style.fontColor ?? '#000000');
  else if (el.type !== 'image' && el.text) label = textSvg(el.text, cx, cy, style);
  return `<g data-id="${id}" data-type="${esc(el.type)}"${tf}>${shape}${label}</g>`;
}

export function renderSVG(items, padding = 10) {
  const boxes = [];
  for (const it of items) {
    if (it.el.type === 'connector') {
      for (const p of it.route || []) boxes.push({ x: p[0], y: p[1], width: 0, height: 0 });
    } else {
      boxes.push(aabbOf(it.el));
    }
  }
  const b = boxes.length ? unionBox(boxes) : { x: 0, y: 0, width: 0, height: 0 };
  const x = b.x - padding;
  const y = b.y - padding;
  const w = Math.max(1, b.width + 2 * padding);
  const h = Math.max(1, b.height + 2 * padding);
  const body = items.map(renderItem).join('\n');
  return `<?xml version="1.0" encoding="UTF-8"?>\n<svg xmlns="http://www.w3.org/2000/svg" viewBox="${num(x)} ${num(y)} ${num(w)} ${num(h)}" width="${num(w)}" height="${num(h)}">\n${body}\n</svg>\n`;
}

