// Diagram document model: operations, undo/redo, queries, CRDT sync and serialization.
//
// State is a set of field registers. Every field of an element or layer holds
// { v, s } where s = [lamportClock, actorId]. A local operation is expanded into
// primitive field writes with fresh stamps; replicas merge writes by taking the
// highest stamp per field, which makes merging commutative, associative and idempotent.
import { DiagramError } from './errors.js';
import { aabbOf, containsPoint, computeRoute, unionBox, toPoint } from './geometry.js';
import { layeredPositions, gridPositions } from './layout.js';
import { parseDrawio, parseStyle, decodeEntities } from './drawio.js';
import { renderSVG } from './svg.js';

export { DiagramError };
export { snap } from './geometry.js';

const SHAPE_TYPES = new Set(['rect', 'ellipse', 'diamond', 'text', 'image', 'line']);
const DEFAULT_LAYER = 'default';
const HISTORY_LIMIT = 500;
const BUILTIN_STAMP = [0, ''];

const fail = (msg) => {
  throw new DiagramError(msg);
};
const rid = (prefix) => `${prefix}_${Math.random().toString(36).slice(2, 10)}`;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const clone = (v) => (v === undefined ? null : v !== null && typeof v === 'object' ? JSON.parse(JSON.stringify(v)) : v);
const newer = (a, b) => !b || a[0] > b[0] || (a[0] === b[0] && a[1] > b[1]);
const cmpStr = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const byId = (a, b) => cmpStr(a.id, b.id);
const sortKeys = (o) => {
  const r = {};
  for (const k of Object.keys(o).sort()) r[k] = o[k];
  return r;
};
const toNum = (v, name) => {
  const n = Number(v);
  if (v === undefined || v === null || !Number.isFinite(n)) fail(`${name} must be a finite number`);
  return n;
};

// Flatten a materialised element or layer into field writes.
function flatten(obj) {
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    if (k === 'id') continue;
    if (k === 'style') {
      for (const [sk, sv] of Object.entries(v || {})) out[`style.${sk}`] = sv;
    } else {
      out[k] = v;
    }
  }
  return out;
}

const zCmp = (a, b) => a.z - b.z || cmpStr(a.id, b.id);

export class Document {
  constructor({ id, actor } = {}) {
    this._id = String(id ?? rid('doc'));
    this._actor = String(actor ?? rid('actor'));
    this._clock = 0;
    this._fields = { e: new Map(), l: new Map() };
    this._seen = new Set();
    this._pending = [];
    this._listeners = new Map();
    this._undoStack = [];
    this._redoStack = [];
    this._batch = null;
    this._putAll('l', DEFAULT_LAYER, { name: 'Layer 1', visible: true, locked: false, order: 0, _deleted: false }, BUILTIN_STAMP);
  }

  get id() {
    return this._id;
  }

  get actor() {
    return this._actor;
  }

  // ---------- raw state ----------

  _put(kind, id, f, v, s) {
    let fm = this._fields[kind].get(id);
    if (!fm) {
      fm = new Map();
      this._fields[kind].set(id, fm);
    }
    const cur = fm.get(f);
    if (newer(s, cur && cur.s)) {
      fm.set(f, { v, s });
      return true;
    }
    return false;
  }

  _putAll(kind, id, fields, s) {
    for (const [f, v] of Object.entries(fields)) this._put(kind, id, f, clone(v), s);
  }

  _mat(kind, id) {
    const fm = this._fields[kind].get(id);
    if (!fm) return undefined;
    const val = (f) => {
      const c = fm.get(f);
      return c && c.v !== undefined ? c.v : null;
    };
    if (val('_deleted') === true) return undefined;
    if (kind === 'l') {
      if (val('name') === null) return undefined;
      return {
        id,
        name: clone(val('name')),
        visible: val('visible') ?? true,
        locked: val('locked') ?? false,
        order: val('order') ?? 0,
      };
    }
    const type = val('type');
    if (type === null) return undefined;
    const out = { id };
    const style = {};
    for (const [f, c] of fm) {
      if (c.v === null || c.v === undefined || f === 'type' || f === '_deleted') continue;
      if (f.startsWith('style.')) style[f.slice(6)] = clone(c.v);
      else out[f] = clone(c.v);
    }
    out.type = type;
    if (type === 'connector') {
      out.source ??= { elementId: null };
      out.target ??= { elementId: null };
      out.routing ??= 'straight';
      out.waypoints ??= [];
      out.label ??= '';
    } else {
      for (const k of ['x', 'y', 'width', 'height']) out[k] ??= 0;
      out.rotation ??= 0;
      out.text ??= '';
    }
    out.layer ??= DEFAULT_LAYER;
    out.groupId ??= null;
    out.z ??= 0;
    out.style = style;
    return sortKeys(out);
  }

  _all(kind) {
    return [...this._fields[kind].keys()];
  }

  _layers() {
    return this._all('l').map((id) => this._mat('l', id)).filter(Boolean);
  }

  _layerMap() {
    return new Map(this._layers().map((l) => [l.id, l]));
  }

  _elementsAll() {
    return this._all('e').map((id) => this._mat('e', id)).filter(Boolean);
  }

  _shapes() {
    return this._elementsAll().filter((e) => e.type !== 'connector');
  }

  _elem(id) {
    const el = this._mat('e', String(id));
    if (!el) fail(`unknown element: ${id}`);
    return el;
  }

  _layer(id) {
    const l = this._mat('l', String(id));
    if (!l) fail(`unknown layer: ${id}`);
    return l;
  }

  _guardLayer(layerId) {
    const l = this._layer(layerId);
    if (l.locked) fail(`layer is locked: ${layerId}`);
  }

  _guard(el) {
    this._guardLayer(el.layer);
  }

  _checkRef(ref) {
    if (ref && ref.elementId != null) this._elem(ref.elementId);
  }

  _normRef(ref) {
    if (!ref || ref.elementId == null) return { elementId: null, ...(ref && ref.point ? { point: toPoint(ref.point) } : {}) };
    return clone({ ...ref, elementId: String(ref.elementId) });
  }

  _ids(ids) {
    if (ids === undefined || ids === null) fail('ids are required');
    return (Array.isArray(ids) ? ids : [ids]).map(String);
  }

  _maxZ(layer) {
    return Math.max(-1, ...this._elementsAll().filter((e) => e.layer === layer).map((e) => e.z));
  }

  // ---------- local writes and transactions ----------

  _w(kind, id, f, value) {
    const b = this._batch;
    let fm = this._fields[kind].get(id);
    if (!fm) {
      fm = new Map();
      this._fields[kind].set(id, fm);
    }
    const key = `${kind}\u0000${id}\u0000${f}`;
    const prev = fm.get(f);
    if (!b.changes.has(key)) {
      b.changes.set(key, {
        kind,
        id,
        f,
        prev: prev ? { v: prev.v, s: prev.s } : null,
        before: prev ? prev.v : null,
        after: null,
      });
    }
    const s = [++this._clock, this._actor];
    fm.set(f, { v: clone(value), s });
    b.writes.push({ k: kind, id, f, v: clone(value), s });
    b.changes.get(key).after = clone(value);
  }

  _setFields(kind, id, patch) {
    for (const [k, v] of Object.entries(patch)) {
      if (v === undefined || k === 'id') continue;
      if (k === 'style') {
        if (isObj(v)) for (const [sk, sv] of Object.entries(v)) this._w(kind, id, `style.${sk}`, sv === undefined ? null : sv);
        continue;
      }
      this._w(kind, id, k, v);
    }
  }

  _rollback(b) {
    for (const c of [...b.changes.values()].reverse()) {
      const fm = this._fields[c.kind].get(c.id);
      if (!fm) continue;
      if (c.prev) fm.set(c.f, c.prev);
      else fm.delete(c.f);
    }
  }

  _run(fn, mode = 'user') {
    const parent = this._batch;
    const b = { writes: [], changes: new Map() };
    this._batch = b;
    let result;
    try {
      result = fn();
    } catch (err) {
      this._rollback(b);
      this._batch = parent;
      throw err;
    }
    this._batch = parent;
    if (parent) {
      parent.writes.push(...b.writes);
      for (const [key, c] of b.changes) {
        const p = parent.changes.get(key);
        if (p) p.after = c.after;
        else parent.changes.set(key, c);
      }
      return result;
    }
    if (b.writes.length === 0) return result;

    const changes = [...b.changes.values()].map((c) => ({ k: c.kind, id: c.id, f: c.f, before: c.before, after: c.after }));
    const op = { id: `${this._actor}:${b.writes[0].s[0]}`, actor: this._actor, writes: b.writes };
    this._seen.add(op.id);
    this._pending.push(op);
    if (mode === 'user') {
      this._redoStack = [];
      this._pushHistory(this._undoStack, changes);
    } else if (mode === 'undo') {
      this._pushHistory(this._redoStack, changes);
    } else {
      this._pushHistory(this._undoStack, changes);
    }
    this._emit('op', clone(op));
    return result;
  }

  _pushHistory(stack, changes) {
    stack.push(changes);
    if (stack.length > HISTORY_LIMIT) stack.shift();
  }

  _emit(name, payload) {
    for (const cb of this._listeners.get(name) ?? []) cb(payload);
  }

  on(name, cb) {
    if (!this._listeners.has(name)) this._listeners.set(name, []);
    this._listeners.get(name).push(cb);
    return () => {
      const list = this._listeners.get(name) ?? [];
      const i = list.indexOf(cb);
      if (i >= 0) list.splice(i, 1);
    };
  }

  transaction(fn) {
    return this._run(() => fn(this), 'user');
  }

  apply(op) {
    return this._run(() => this._applyOp(op), 'user');
  }

  _applyOp(op) {
    if (!isObj(op)) fail('operation must be an object');
    switch (op.type) {
      case 'add':
        return this._add(op.element);
      case 'update':
        return this._update(op.id, op.patch);
      case 'remove':
        return this._remove(op.id);
      case 'move':
        return this._move(op.ids, op.dx, op.dy);
      case 'resize':
        return this._resize(op.id, op.box, op.keepAspect);
      case 'rotate':
        return this._rotate(op.id, op.deg);
      case 'group':
        return this._group(op.ids, op.groupId);
      case 'ungroup':
        return this._ungroup(op.groupId);
      case 'reorder':
        return this._reorder(op.id, op.to);
      case 'addLayer':
        return this._addLayer(op.layer);
      case 'updateLayer':
        return this._updateLayer(op.id, op.patch);
      case 'removeLayer':
        return this._removeLayer(op.id);
      case 'setStyle':
        return this._setStyle(op.ids, op.style);
      default:
        return fail(`unknown operation type: ${op.type}`);
    }
  }

  undo() {
    const entry = this._undoStack.pop();
    if (!entry) return false;
    this._run(() => {
      for (const c of entry) this._w(c.k, c.id, c.f, c.before);
    }, 'undo');
    return true;
  }

  redo() {
    const entry = this._redoStack.pop();
    if (!entry) return false;
    this._run(() => {
      for (const c of entry) this._w(c.k, c.id, c.f, c.before);
    }, 'redo');
    return true;
  }

  clearHistory() {
    this._undoStack = [];
    this._redoStack = [];
  }

  // ---------- operations ----------

  _add(src) {
    if (!isObj(src)) fail('add requires an element');
    const type = src.type;
    if (type !== 'connector' && !SHAPE_TYPES.has(type)) fail(`unknown element type: ${type}`);
    const id = src.id === undefined || src.id === null ? rid(type) : String(src.id);
    if (this._mat('e', id)) fail(`element already exists: ${id}`);
    const layer = src.layer ?? DEFAULT_LAYER;
    this._guardLayer(layer);
    const patch = { ...src, id, layer, _deleted: false };
    for (const k of ['x', 'y', 'width', 'height', 'rotation']) {
      if (src[k] !== undefined) patch[k] = toNum(src[k], k);
    }
    if (type === 'connector') {
      this._checkRef(src.source);
      this._checkRef(src.target);
      patch.source = this._normRef(src.source);
      patch.target = this._normRef(src.target);
    }
    patch.z = src.z === undefined ? this._maxZ(layer) + 1 : toNum(src.z, 'z');
    this._setFields('e', id, patch);
    return id;
  }

  _update(id, patch) {
    const el = this._elem(id);
    if (!isObj(patch)) fail('update requires a patch');
    if (patch.type !== undefined && patch.type !== el.type) fail('element type cannot be changed');
    this._guard(el);
    if (patch.layer !== undefined) this._guardLayer(patch.layer);
    const p = { ...patch };
    delete p.id;
    delete p.type;
    delete p._deleted;
    if (p.source !== undefined) {
      this._checkRef(p.source);
      p.source = this._normRef(p.source);
    }
    if (p.target !== undefined) {
      this._checkRef(p.target);
      p.target = this._normRef(p.target);
    }
    this._setFields('e', el.id, p);
  }

  _remove(id) {
    const el = this._elem(id);
    this._guard(el);
    const attached = this._elementsAll().filter(
      (c) =>
        c.type === 'connector' &&
        c.id !== el.id &&
        ((c.source && c.source.elementId === el.id) || (c.target && c.target.elementId === el.id)),
    );
    for (const c of attached) this._guard(c);
    this._w('e', el.id, '_deleted', true);
    for (const c of attached) this._w('e', c.id, '_deleted', true);
  }

  _move(ids, dx, dy) {
    const ddx = toNum(dx, 'dx');
    const ddy = toNum(dy, 'dy');
    for (const id of this._ids(ids)) {
      const el = this._elem(id);
      if (el.type === 'connector') continue;
      this._guard(el);
      this._w('e', el.id, 'x', el.x + ddx);
      this._w('e', el.id, 'y', el.y + ddy);
    }
  }

  _resize(id, box, keepAspect) {
    const el = this._elem(id);
    if (el.type === 'connector') fail('connectors cannot be resized');
    this._guard(el);
    if (!isObj(box)) fail('box is required');
    let x = toNum(box.x, 'box.x');
    let y = toNum(box.y, 'box.y');
    let width = toNum(box.width, 'box.width');
    let height = toNum(box.height, 'box.height');
    if (keepAspect && el.width > 0 && el.height > 0) {
      const ratio = el.width / el.height;
      if (width / height > ratio) width = height * ratio;
      else height = width / ratio;
    }
    this._w('e', el.id, 'x', x);
    this._w('e', el.id, 'y', y);
    this._w('e', el.id, 'width', width);
    this._w('e', el.id, 'height', height);
  }

  _rotate(id, deg) {
    const el = this._elem(id);
    if (el.type === 'connector') fail('connectors cannot be rotated');
    this._guard(el);
    this._w('e', el.id, 'rotation', toNum(deg, 'deg'));
  }

  _group(ids, groupId) {
    const list = this._ids(ids).map((id) => this._elem(id));
    const gid = groupId !== undefined && groupId !== null ? String(groupId) : rid('group');
    for (const el of list) {
      this._guard(el);
      this._w('e', el.id, 'groupId', gid);
    }
    return gid;
  }

  _ungroup(groupId) {
    const members = this._elementsAll().filter((e) => e.groupId === String(groupId));
    if (!members.length) fail(`unknown group: ${groupId}`);
    for (const el of members) {
      this._guard(el);
      this._w('e', el.id, 'groupId', null);
    }
  }

  _reorder(id, to) {
    const el = this._elem(id);
    this._guard(el);
    const sibs = this._elementsAll().filter((e) => e.layer === el.layer).sort(zCmp);
    const others = sibs.filter((e) => e.id !== el.id);
    if (!others.length) return;
    let z;
    switch (to) {
      case 'front':
        z = Math.max(...others.map((e) => e.z)) + 1;
        break;
      case 'back':
        z = Math.min(...others.map((e) => e.z)) - 1;
        break;
      case 'forward': {
        const above = others.filter((e) => e.z > el.z).sort(zCmp);
        if (!above.length) return;
        const next = above[1];
        z = next ? (above[0].z + next.z) / 2 : above[0].z + 1;
        break;
      }
      case 'backward': {
        const below = others.filter((e) => e.z < el.z).sort(zCmp).reverse();
        if (!below.length) return;
        const next = below[1];
        z = next ? (below[0].z + next.z) / 2 : below[0].z - 1;
        break;
      }
      default:
        fail(`unknown reorder target: ${to}`);
    }
    this._w('e', el.id, 'z', z);
  }

  _addLayer(layer) {
    if (!isObj(layer)) fail('addLayer requires a layer');
    const id = layer.id === undefined || layer.id === null ? rid('layer') : String(layer.id);
    if (this._mat('l', id)) fail(`layer already exists: ${id}`);
    const order = Math.max(-1, ...this._layers().map((l) => l.order)) + 1;
    this._setFields('l', id, {
      name: layer.name ?? id,
      visible: layer.visible ?? true,
      locked: layer.locked ?? false,
      order,
      _deleted: false,
    });
    return id;
  }

  _updateLayer(id, patch) {
    const l = this._layer(id);
    if (!isObj(patch)) fail('updateLayer requires a patch');
    const allowed = ['name', 'visible', 'locked', 'order'];
    for (const k of Object.keys(patch)) {
      if (!allowed.includes(k)) continue;
      this._w('l', l.id, k, patch[k]);
    }
  }

  _removeLayer(id) {
    if (String(id) === DEFAULT_LAYER) fail('the default layer cannot be removed');
    const l = this._layer(id);
    if (l.locked) fail(`layer is locked: ${l.id}`);
    for (const e of this._elementsAll()) {
      if (e.layer === l.id) this._w('e', e.id, 'layer', DEFAULT_LAYER);
    }
    this._w('l', l.id, '_deleted', true);
  }

  _setStyle(ids, style) {
    if (!isObj(style)) fail('style must be an object');
    for (const id of this._ids(ids)) {
      const el = this._elem(id);
      this._guard(el);
      for (const [k, v] of Object.entries(style)) this._w('e', el.id, `style.${k}`, v === undefined ? null : v);
    }
  }

  // ---------- queries ----------

  get(id) {
    return this._mat('e', String(id));
  }

  layers() {
    return this._layers().sort((a, b) => a.order - b.order || cmpStr(a.id, b.id));
  }

  elements({ layer, type } = {}) {
    const layers = this._layerMap();
    const ord = (id) => (layers.get(id) ? layers.get(id).order : -1);
    let list = this._elementsAll();
    if (layer !== undefined) list = list.filter((e) => e.layer === layer);
    if (type !== undefined) list = list.filter((e) => e.type === type);
    return list.sort((a, b) => ord(a.layer) - ord(b.layer) || cmpStr(a.layer, b.layer) || zCmp(a, b));
  }

  hitTest(x, y) {
    const layers = this._layerMap();
    const list = this.elements().filter((e) => e.type !== 'connector');
    for (let i = list.length - 1; i >= 0; i--) {
      const e = list[i];
      const l = layers.get(e.layer);
      if (l && !l.visible) continue;
      if (containsPoint(e, x, y)) return e;
    }
    return null;
  }

  select(rect) {
    const out = [];
    for (const e of this.elements()) {
      if (e.type === 'connector') continue;
      const b = aabbOf(e);
      if (
        b.x >= rect.x &&
        b.y >= rect.y &&
        b.x + b.width <= rect.x + rect.width &&
        b.y + b.height <= rect.y + rect.height
      ) {
        out.push(e.id);
      }
    }
    return out;
  }

  bounds(ids) {
    const items = ids === undefined ? this._shapes() : this._ids(ids).map((id) => this._elem(id));
    const boxes = [];
    for (const e of items) {
      if (e.type === 'connector') {
        for (const p of this.route(e.id)) boxes.push({ x: p[0], y: p[1], width: 0, height: 0 });
      } else {
        boxes.push(aabbOf(e));
      }
    }
    if (!boxes.length) return null;
    return unionBox(boxes);
  }

  // ---------- geometry operations ----------

  align(ids, mode) {
    const modes = ['left', 'center', 'right', 'top', 'middle', 'bottom'];
    if (!modes.includes(mode)) fail(`unknown align mode: ${mode}`);
    const list = this._ids(ids).map((id) => this._elem(id)).filter((e) => e.type !== 'connector');
    if (!list.length) return;
    const b = unionBox(list.map(aabbOf));
    this.transaction(() => {
      for (const e of list) {
        const a = aabbOf(e);
        let dx = 0;
        let dy = 0;
        switch (mode) {
          case 'left':
            dx = b.x - a.x;
            break;
          case 'center':
            dx = b.x + b.width / 2 - (a.x + a.width / 2);
            break;
          case 'right':
            dx = b.x + b.width - (a.x + a.width);
            break;
          case 'top':
            dy = b.y - a.y;
            break;
          case 'middle':
            dy = b.y + b.height / 2 - (a.y + a.height / 2);
            break;
          default:
            dy = b.y + b.height - (a.y + a.height);
        }
        if (dx || dy) this._move([e.id], dx, dy);
      }
    });
  }

  distribute(ids, dir) {
    if (dir !== 'horizontal' && dir !== 'vertical') fail(`unknown distribute direction: ${dir}`);
    const horiz = dir === 'horizontal';
    const list = this._ids(ids).map((id) => this._elem(id)).filter((e) => e.type !== 'connector');
    if (list.length < 3) return;
    const items = list.map((e) => ({ e, a: aabbOf(e) }));
    items.sort((p, q) => (horiz ? p.a.x - q.a.x : p.a.y - q.a.y) || cmpStr(p.e.id, q.e.id));
    const n = items.length;
    const size = (a) => (horiz ? a.width : a.height);
    const pos = (a) => (horiz ? a.x : a.y);
    const first = items[0].a;
    const last = items[n - 1].a;
    const start = pos(first);
    const end = pos(last) + size(last);
    const sizes = items.reduce((s, it) => s + size(it.a), 0);
    const gap = (end - start - sizes) / (n - 1);
    this.transaction(() => {
      let cursor = start;
      for (const it of items) {
        const delta = cursor - pos(it.a);
        if (delta) this._move([it.e.id], horiz ? delta : 0, horiz ? 0 : delta);
        cursor += size(it.a) + gap;
      }
    });
  }

  // ---------- routing and layout ----------

  route(id) {
    const conn = this._elem(id);
    if (conn.type !== 'connector') fail(`not a connector: ${id}`);
    return computeRoute(conn, (rid2) => this._mat('e', String(rid2)), this._shapes());
  }

  layout(kind, opts = {}) {
    const shapes = this._shapes();
    const spacing = opts.spacing === undefined ? 40 : toNum(opts.spacing, 'spacing');
    let pos;
    if (kind === 'layered') {
      const direction = opts.direction ?? 'TB';
      if (direction !== 'TB' && direction !== 'LR') fail(`unknown direction: ${direction}`);
      const nodes = shapes.map((s) => ({ id: s.id, width: s.width, height: s.height }));
      const ids = new Set(shapes.map((s) => s.id));
      const edges = this._elementsAll()
        .filter((c) => c.type === 'connector')
        .map((c) => ({ from: c.source && c.source.elementId, to: c.target && c.target.elementId }))
        .filter((e) => ids.has(e.from) && ids.has(e.to));
      pos = layeredPositions(nodes, edges, { direction, spacing });
    } else if (kind === 'grid') {
      pos = gridPositions(shapes.map((s) => ({ id: s.id, width: s.width, height: s.height })), { spacing });
    } else {
      fail(`unknown layout: ${kind}`);
    }
    this.transaction(() => {
      for (const s of shapes) {
        const p = pos.get(s.id);
        if (!p || (p.x === s.x && p.y === s.y)) continue;
        this._guard(s);
        this._w('e', s.id, 'x', p.x);
        this._w('e', s.id, 'y', p.y);
      }
    });
  }

  // ---------- collaboration ----------

  pendingOps() {
    const out = this._pending;
    this._pending = [];
    return clone(out);
  }

  hasOp(opId) {
    return this._seen.has(opId);
  }

  receive(ops) {
    const list = Array.isArray(ops) ? ops : [ops];
    let applied = 0;
    for (const op of list) {
      if (!isObj(op) || typeof op.id !== 'string' || !Array.isArray(op.writes)) fail('invalid operation in batch');
      if (this._seen.has(op.id)) continue;
      this._seen.add(op.id);
      applied++;
      for (const w of op.writes) {
        if (!Array.isArray(w.s)) fail('invalid write stamp');
        this._clock = Math.max(this._clock, Number(w.s[0]) || 0);
        this._put(w.k, w.id, w.f, clone(w.v), [Number(w.s[0]), String(w.s[1])]);
      }
    }
    return applied;
  }

  // Replace the content with the given JSON snapshot as a single local (undoable) step.
  restore(input) {
    const json = typeof input === 'string' ? JSON.parse(input) : input;
    const target = { e: new Map(), l: new Map() };
    for (const l of json.layers ?? []) target.l.set(l.id, flatten({ ...l, _deleted: false }));
    for (const el of json.elements ?? []) target.e.set(el.id, { ...flatten(el), _deleted: false });
    this._run(() => {
      for (const kind of ['l', 'e']) {
        const tgt = target[kind];
        const cur = this._fields[kind];
        for (const id of new Set([...cur.keys(), ...tgt.keys()])) {
          const want = tgt.get(id);
          const fm = cur.get(id);
          const fields = new Set([...(fm ? fm.keys() : []), ...(want ? Object.keys(want) : [])]);
          for (const f of fields) {
            const curV = fm && fm.get(f) ? fm.get(f).v : null;
            let wantV;
            if (want) wantV = f in want ? want[f] : null;
            else wantV = f === '_deleted' ? true : curV;
            if (JSON.stringify(curV) !== JSON.stringify(wantV ?? null)) this._w(kind, id, f, wantV ?? null);
          }
        }
      }
    }, 'user');
  }

  // ---------- serialization ----------

  toJSON() {
    const dump = (map) => {
      const out = {};
      for (const id of [...map.keys()].sort()) {
        const fm = map.get(id);
        const f = {};
        for (const k of [...fm.keys()].sort()) {
          const c = fm.get(k);
          f[k] = [c.v === undefined ? null : c.v, c.s[0], c.s[1]];
        }
        out[id] = f;
      }
      return out;
    };
    return {
      format: 'diagram-s5',
      version: 1,
      id: this._id,
      layers: this.layers(),
      elements: this._elementsAll().sort(byId),
      crdt: { e: dump(this._fields.e), l: dump(this._fields.l) },
      ops: [...this._seen].sort(),
    };
  }

  _loadJSON(json) {
    if (json.crdt) {
      const load = (obj) => {
        const map = new Map();
        for (const [id, fields] of Object.entries(obj || {})) {
          const fm = new Map();
          for (const [f, [v, c, a]] of Object.entries(fields)) fm.set(f, { v: v ?? null, s: [Number(c), String(a)] });
          map.set(id, fm);
        }
        return map;
      };
      this._fields = { e: load(json.crdt.e), l: load(json.crdt.l) };
      this._seen = new Set(json.ops || []);
      let clock = 0;
      for (const kind of ['e', 'l']) {
        for (const fm of this._fields[kind].values()) {
          for (const c of fm.values()) clock = Math.max(clock, c.s[0]);
        }
      }
      this._clock = clock;
      return;
    }
    // Plain JSON without CRDT state: every field becomes a write at a fixed stamp.
    this._fields = { e: new Map(), l: new Map() };
    this._seen = new Set();
    this._clock = 1;
    const stamp = [1, 'json'];
    for (const l of json.layers ?? []) this._putAll('l', l.id, { ...flatten(l), _deleted: false }, stamp);
    if (!this._mat('l', DEFAULT_LAYER)) this._putAll('l', DEFAULT_LAYER, { name: 'Layer 1', visible: true, locked: false, order: 0, _deleted: false }, BUILTIN_STAMP);
    for (const el of json.elements ?? []) this._putAll('e', el.id, { ...flatten(el), _deleted: false }, stamp);
  }

  toSVG({ padding = 10 } = {}) {
    const layers = this._layerMap();
    const shapes = this._shapes();
    const items = this.elements()
      .filter((e) => {
        const l = layers.get(e.layer);
        return !l || l.visible;
      })
      .map((el) => ({
        el,
        route: el.type === 'connector' ? computeRoute(el, (x) => this._mat('e', String(x)), shapes) : null,
      }));
    return renderSVG(items, padding);
  }
}

export function createDocument(opts = {}) {
  return new Document(opts);
}

export function fromJSON(input, opts = {}) {
  const json = typeof input === 'string' ? JSON.parse(input) : input;
  if (!isObj(json)) fail('invalid document JSON');
  const doc = new Document({ id: json.id ?? opts.id, actor: opts.actor });
  doc._loadJSON(json);
  return doc;
}

export function importDrawio(xml, opts = {}) {
  const text = String(xml ?? '');
  if (!/<mxCell\b/.test(text)) fail('not a draw.io (mxGraph) document: no mxCell found');
  const cells = parseDrawio(text);
  const lookup = new Map(cells.filter((c) => c.id !== undefined).map((c) => [String(c.id), c]));

  // Absolute position: geometry is relative to the parent vertex when nested.
  const offsetOf = (c) => {
    let x = 0;
    let y = 0;
    let p = c;
    const seen = new Set();
    while (p && p.parent && lookup.has(p.parent) && lookup.get(p.parent).vertex && !seen.has(p.parent)) {
      seen.add(p.parent);
      p = lookup.get(p.parent);
      if (p.geometry) {
        x += p.geometry.x;
        y += p.geometry.y;
      }
    }
    return { x, y };
  };

  const mapStyle = (m) => {
    const out = {};
    if (m.fillColor && m.fillColor !== 'none') out.fill = m.fillColor;
    if (m.strokeColor && m.strokeColor !== 'none') out.stroke = m.strokeColor;
    if (m.strokeWidth !== undefined) out.strokeWidth = Number(m.strokeWidth);
    if (m.fontColor) out.fontColor = m.fontColor;
    if (m.fontSize) out.fontSize = Number(m.fontSize);
    if (m.fontFamily) out.fontFamily = m.fontFamily;
    if (m.opacity) out.opacity = Number(m.opacity);
    return out;
  };
  const labelOf = (c, s) => {
    let t = c.value;
    if (s.map.html === '1') t = t.replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '');
    return decodeEntities(t);
  };

  const doc = createDocument({ id: opts.id ?? 'imported', actor: opts.actor ?? 'import' });
  const imported = new Set();
  for (const c of cells) {
    if (!c.vertex || !c.geometry || c.id === undefined) continue;
    const s = parseStyle(c.style);
    const shape = s.map.shape ?? '';
    let type = 'rect';
    if (s.bare.has('ellipse') || shape === 'ellipse') type = 'ellipse';
    else if (s.bare.has('rhombus') || shape === 'rhombus') type = 'diamond';
    else if (shape === 'image' || s.map.image !== undefined) type = 'image';
    else if (s.bare.has('text') || s.map.text === '1') type = 'text';
    else if (shape === 'line') type = 'line';
    const off = offsetOf(c);
    const id = String(c.id);
    const el = {
      id,
      type,
      x: c.geometry.x + off.x,
      y: c.geometry.y + off.y,
      width: c.geometry.width,
      height: c.geometry.height,
      rotation: s.map.rotation !== undefined ? Number(s.map.rotation) : 0,
      style: mapStyle(s.map),
      text: type === 'image' ? decodeEntities(s.map.image ?? '') : labelOf(c, s),
    };
    doc.apply({ type: 'add', element: el });
    imported.add(id);
  }
  for (const c of cells) {
    if (!c.edge || c.id === undefined) continue;
    const s = parseStyle(c.style);
    const endRef = (ref, point) =>
      ref !== null && imported.has(String(ref))
        ? { elementId: String(ref) }
        : { elementId: null, point: point ? [point.x, point.y] : [0, 0] };
    doc.apply({
      type: 'add',
      element: {
        id: String(c.id),
        type: 'connector',
        source: endRef(c.source, c.sourcePoint),
        target: endRef(c.target, c.targetPoint),
        routing: /orthogonal/i.test(s.map.edgeStyle || '') ? 'orthogonal' : 'straight',
        waypoints: c.waypoints.map((p) => [p.x, p.y]),
        label: labelOf(c, s),
        style: mapStyle(s.map),
      },
    });
  }
  doc.clearHistory();
  return doc;
